"""Local-only P10 bridge to the Lab's existing decide(case, threads) interface.

No closing authority, provider credentials, remote execution or document hydration.
The simulator must terminate the session; this bridge only sends validated offers/questions.
"""

import asyncio
import hashlib
import json
import os
import time
from datetime import UTC, datetime
from pathlib import Path

from ..core import models as m
from ..core.errors import ContractViolation
from ..core.serialization import semantic_hash
from .chat_completions import ChatCompletionConfig
from .offline import OfflineRecordedInputs
from .p10 import recorded_p10


class WallClock:
    def utcnow(self):
        return datetime.now(UTC)

    def monotonic(self):
        return time.monotonic()


class LocalFixtureTransport:
    """Scripted ambiguity/minimum responses; measures plumbing, never model intelligence."""

    async def __call__(self, request, budget):
        if request.task == "interpret":
            observations = []
            for index, msg in enumerate(request.input.conversation.messages):
                if not msg.body:
                    continue
                span = m.MessageSpan(session_id=msg.session_id, thread_id=msg.thread_id,
                                     message_id=msg.message_id, start=0, end=len(msg.body), quote=msg.body)
                observations.append(m.GroundedObservation(
                    observation_id=f"observation:{index}", kind="ambiguity", dimension=None,
                    summary=msg.body, citations=(span,),
                ))
            response = m.AssessmentDraft(observations=tuple(observations), reported_constraints=(),
                                         hypotheses=(), uncertainties=(), questions=(), unknowns=())
        else:
            # Read the authoritative zero delta; perform no economic arithmetic.
            choices = [o for o in request.input.options if "cost delta from cheapest=0 " in o.summary]
            if not choices:
                raise ContractViolation("unsupported_capability: fixture expects an official minimum offer")
            response = m.SelectorResponse(selected_id=min(o.candidate_id for o in choices), supporting_quote="")
        raw = response.model_dump_json()
        return m.ModelSuccess(kind="success", call_id=request.call_id, model_id=request.model_id,
                              elapsed_s=0, issues=(), raw_response_json=raw,
                              response_hash=hashlib.sha256(raw.encode()).hexdigest(), usage=m.ModelUsage())


class LocalV2LabAgent:
    local_only = True
    version = "v2-lab-p10-local/1"

    def __init__(self, *, dataset_path, trace_root, arm="grounded", clock=None, transport=None):
        if arm not in {"minimum", "direct", "grounded"}:
            raise ValueError("unknown bounded strategy arm")
        self.dataset = json.loads(Path(dataset_path).read_text())
        self.arm, self.clock = arm, clock or WallClock()
        self.transport = transport or LocalFixtureTransport()
        self.trace_root = Path(trace_root)
        self.traces = []
        self.previous = None
        self.observation = None
        self.session_id = None
        self.run_id = None

    def observe_lab_session(self, run_id, session_id):
        """Identity supplied by RecordingTable after the actual session is opened."""
        if self.session_id is not None:
            raise ContractViolation("scope_mismatch: one agent per Lab attempt")
        self.run_id, self.session_id = run_id, session_id

    def decide(self, case, threads):
        from ..factory import bounded_services, run_recorded_decision

        if case != self.dataset["case"] or not self.session_id:
            raise ContractViolation("unsupported_capability: reviewed P10 local Lab session required")
        supplier = case["suppliers"][0]
        events = threads[supplier]
        count = sum(e.get("from") == "buyer" for e in events)
        if count >= case["round_limit"]:
            raise ContractViolation("unsupported_capability: V2 closing authority remains unavailable")
        observation = semantic_hash(events)
        if observation == self.observation:
            raise ContractViolation("recovery_required: duplicate observation requires reconciliation")
        now = self.clock.utcnow()
        supplier_events = [(i, e) for i, e in enumerate(events) if e.get("from") != "buyer"]
        # Explicit local purpose projection: bodies/identities only. PDFs, sheets and private
        # economics never enter model input. Case fields/packages remain typed authoritative inputs.
        bodies = [e.get("body", "") for _, e in supplier_events]
        dataset = {**self.dataset, "supplier_messages": bodies}
        inputs = recorded_p10(dataset, message=bodies[-1], now=now,
                              model_call_limit=0 if self.arm == "minimum" else 2)
        messages = tuple(m.ConversationMessage(
            session_id=self.session_id, thread_id=e["thread_id"], message_id=e["message_id"],
            supplier_id=supplier, speaker="supplier", body=e.get("body", ""), observed_sheets=(),
            attachments=(), claim_results=(), received_at=now,
            content_hash=hashlib.sha256(e.get("body", "").encode()).hexdigest(),
        ) for _, e in supplier_events)
        conversation = m.ConversationView(session_id=self.session_id, thread_id=messages[0].thread_id,
                                          messages=messages, version_hash=semantic_hash(messages))
        thread = inputs.server.threads[0].model_copy(update={
            "thread_id": conversation.thread_id, "conversation": conversation,
            "rounds": inputs.server.threads[0].rounds.model_copy(update={
                "accepted_buyer_messages": count, "conservative_remaining": case["round_limit"] - count,
            }),
        })
        server = inputs.server.model_copy(update={
            "session_id": self.session_id, "threads": (thread,), "observation_hash": observation,
        })
        strategic = inputs.state.strategic.model_copy(update={
            "assessments": (self.previous,) if self.previous else (),
        })
        state = inputs.state.model_copy(update={
            "run_id": self.run_id, "server": server, "version": count, "strategic": strategic,
            "config_hash": semantic_hash((self.version, self.arm, self.dataset)),
        })
        inputs = OfflineRecordedInputs.model_validate_json(inputs.model_copy(update={
            "server": server, "state": state, "previous_assessment": self.previous,
        }).model_dump_json())
        config = ChatCompletionConfig(base_url="http://localhost/v1", provider_id="local-fixture",
                                      model_id="explicit-scripted-fixture", structured_output=True)
        assembler, coordinator = bounded_services(
            inputs, self.clock, self.transport if self.arm != "minimum" else None,
            config, prompt_revision="v2", arm=self.arm,
        )
        trace = asyncio.run(run_recorded_decision(inputs, assembler=assembler, coordinator=coordinator))
        trace.verify()
        directory = self.trace_root / self.run_id / self.session_id
        directory.mkdir(parents=True, exist_ok=True, mode=0o700)
        path = directory / f"decision-{count:03d}.json"
        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(descriptor, "w") as output:
            output.write(trace.model_dump_json())
        self.traces.append(trace)
        if trace.validation is None or trace.validation.kind != "valid" or trace.validated_message_bytes is None:
            raise ContractViolation("infeasible: local V2 decision did not pass independent validation")
        self.previous, self.observation = trace.assessment, observation
        return {"supplier_id": supplier, "message": json.loads(trace.validated_message_bytes)}

    def experiment_metrics(self):
        from ..orchestration.metrics import decision_metrics

        return {"evidence": "local scripted model; official contract simulator outcomes",
                "arm": self.arm, "decisions": [decision_metrics(t) for t in self.traces]}

